import * as THREE from 'three';
// Camera-independent trackball rotation allows true overturns without OrbitControls' polar limit.
export function createGestureScene({scene,camera,cell,controls,canvas,pick,selectHit,invalidate,cancelMotion}){
 const initial=cell.quaternion.clone(),overlay=new THREE.Group();scene.add(overlay);let hit=null,fill=null,halo=null,start=0,frame=0,baseScale=new THREE.Vector3(),lastHover=0;
 function clear(){cancelAnimationFrame(frame);frame=0;hit=null;for(const child of [...overlay.children]){overlay.remove(child);child.material.dispose();}fill=halo=null;invalidate();}
 function update(){if(!hit||!hit.object.parent){clear();return;}const matrix=hit.object.matrixWorld.clone();if(hit.object.isInstancedMesh){const m=new THREE.Matrix4();hit.object.getMatrixAt(hit.instanceId,m);matrix.multiply(m);}matrix.decompose(overlay.position,overlay.quaternion,baseScale);const t=Math.min(1,(performance.now()-start)/160);overlay.scale.copy(baseScale).multiplyScalar(1+.065*(1-(1-t)**3));invalidate();if(t<1)frame=requestAnimationFrame(update);}
 function hover(x,y){if(performance.now()-lastHover<65)return !!hit;lastHover=performance.now();const rect=canvas.getBoundingClientRect();if(x<rect.left||x>rect.right||y<rect.top||y>rect.bottom){clear();return false;}const next=pick({clientX:x,clientY:y});if(next?.object===hit?.object&&next?.instanceId===hit?.instanceId){if(hit){cancelAnimationFrame(frame);update();}return !!hit;}clear();if(!next)return false;hit=next;start=performance.now();const material=new THREE.MeshStandardMaterial({color:next.object.material.color,roughness:.4,metalness:.06,clippingPlanes:next.object.material.clippingPlanes,side:THREE.DoubleSide});if(next.object.isInstancedMesh&&next.object.instanceColor){const color=new THREE.Color();next.object.getColorAt(next.instanceId,color);material.color.multiply(color);}fill=new THREE.Mesh(next.object.geometry,material);fill.renderOrder=5;overlay.add(fill);
  const glow=new THREE.ShaderMaterial({uniforms:{glowColor:{value:new THREE.Color('#ff3e54')}},vertexShader:'#include <clipping_planes_pars_vertex>\nvarying vec3 vN; varying vec3 vV; void main(){vec4 mvPosition=modelViewMatrix*vec4(position,1.0);vN=normalize(normalMatrix*normal);vV=-mvPosition.xyz;gl_Position=projectionMatrix*mvPosition;\n#include <clipping_planes_vertex>\n}',fragmentShader:'#include <clipping_planes_pars_fragment>\nuniform vec3 glowColor; varying vec3 vN; varying vec3 vV;void main(){\n#include <clipping_planes_fragment>\nfloat rim=pow(1.0-abs(dot(normalize(vN),normalize(vV))),2.0);gl_FragColor=vec4(glowColor,rim*.8);}',transparent:true,depthWrite:false,side:THREE.DoubleSide,clipping:true,clippingPlanes:material.clippingPlanes});halo=new THREE.Mesh(next.object.geometry,glow);halo.scale.setScalar(1.12);halo.renderOrder=6;overlay.add(halo);update();return true;
 }
 function click(x,y){const h=pick({clientX:x,clientY:y});clear();if(h)selectHit(h);return !!h;}
 return {hover,click,clear,rotate(dx,dy,roll=0){clear();cancelMotion();const right=new THREE.Vector3(1,0,0).applyQuaternion(camera.quaternion),up=new THREE.Vector3(0,1,0).applyQuaternion(camera.quaternion),forward=new THREE.Vector3(0,0,1).applyQuaternion(camera.quaternion);cell.quaternion.premultiply(new THREE.Quaternion().setFromAxisAngle(up,dx));cell.quaternion.premultiply(new THREE.Quaternion().setFromAxisAngle(right,dy));cell.quaternion.premultiply(new THREE.Quaternion().setFromAxisAngle(forward,roll));cell.quaternion.normalize();invalidate();},zoom(delta){clear();cancelMotion();const offset=camera.position.clone().sub(controls.target),distance=THREE.MathUtils.clamp(offset.length()*Math.exp(-delta),controls.minDistance,controls.maxDistance);camera.position.copy(controls.target).add(offset.setLength(distance));controls.update();invalidate();},reset(){clear();cell.quaternion.copy(initial);invalidate();},debug(){return {hovered:!!hit,component:hit?.object.userData.component,instance:hit?.instanceId,halo:!!halo,scale:overlay.scale.toArray()};}};
}
